/* js/audio/sfx.js — sound effects. Real MP3 files from assets/sfx (generated by tools/make_sfx.py) decoded once
   into AudioBuffers; a tiny synth blip is the fallback if a file is missing. Silent until the visitor's first tap. */
import * as engine from './engine.js';
import { asset, rnd } from '../core/util.js';
import * as settings from '../core/settings.js';

const buf = new Map();           // name -> AudioBuffer | null (failed) | Promise
const lastAt = new Map();
let out = null;

function dest() {
  const c = engine.ctx(); if (!c) return null;
  if (!out || out.context !== c) { out = c.createGain(); out.connect(c.destination); }
  return out;
}
function load(name) {
  if (buf.has(name)) return buf.get(name);
  const c = engine.ctx(); if (!c) return null;
  const p = fetch(asset(`assets/sfx/${name}.mp3`)).then(r => { if (!r.ok) throw 0; return r.arrayBuffer(); })
    .then(ab => new Promise((res, rej) => c.decodeAudioData(ab, res, rej)))
    .then(b => { buf.set(name, b); return b; }).catch(() => { buf.set(name, null); return null; });
  buf.set(name, p); return p;
}
export const preload = names => names.forEach(load);

export function play(name, { vol = 1, rate = 1, minGap = 0.035, force = false } = {}) {
  const c = engine.ctx();
  if (!c || c.state !== 'running' || (!settings.set.sfx && !force)) return;
  const now = performance.now() / 1000; if (now - (lastAt.get(name) || 0) < minGap) return; lastAt.set(name, now);
  let b = buf.get(name);
  if (b === undefined) { load(name); return; }                // first call just warms the cache (hover sounds etc.)
  if (b instanceof Promise) return;
  if (b === null) { blip(300 * rate, 0.05, 'square', 0.02 * vol); return; }
  try {
    const src = c.createBufferSource(), g = c.createGain(); src.buffer = b; src.playbackRate.value = rate;
    g.gain.value = vol * settings.set.sfxVol * (engine.isMuted() ? 0.35 : 1) * Math.max(0.35, engine.getDuck());
    src.connect(g); g.connect(dest()); src.start();
  } catch (e) {}
}
/* play now even if it needs loading first (for important sounds: loads then plays) */
export function playNow(name, opts) {
  const b = buf.get(name);
  if (b === undefined) { const p = load(name); if (p) p.then(() => play(name, opts)); return; }
  play(name, opts);
}
export const variant = (base, n, opts) => playNow(`${base}_${1 + ((Math.random() * n) | 0)}`, opts);

/* fallback synth blip (the original site's sound) */
export function blip(f = 220, dur = 0.06, type = 'square', v = 0.025) {
  const c = engine.ctx();
  if (!c || c.state !== 'running' || !settings.set.sfx) return;
  try {
    const o = c.createOscillator(), g = c.createGain(), n = c.currentTime;
    o.type = type; o.frequency.setValueAtTime(f, n);
    o.frequency.exponentialRampToValueAtTime(Math.max(30, f * rnd(0.25, 3)), n + dur);
    g.gain.setValueAtTime(v * settings.set.sfxVol, n); g.gain.exponentialRampToValueAtTime(0.0001, n + dur);
    o.connect(g); g.connect(c.destination); o.start(); o.stop(n + dur);
  } catch (e) {}
}
export const CORE = ['ui_click', 'ui_hover', 'ui_toggle_on', 'ui_toggle_off', 'ui_open', 'ui_close', 'whoosh_a', 'whoosh_b', 'whoosh_glitch', 'bot_msg', 'bot_send', 'bot_open', 'bot_type', 'censor_1', 'censor_2', 'censor_3', 'theme_day', 'theme_night', 'enter', 'ui_copy', 'ui_success', 'ui_error'];
